using System.Globalization;
using System.Resources;

namespace Custos.Core;

/// <summary>
/// Texts the service writes into run logs and the live log of the interface (Resources\Messages.tsv: English and
/// Russian). The properties are generated by tools/make-strings.py into Messages.g.cs.
/// </summary>
public static partial class Messages
{
    private static readonly ResourceManager Resources = new("Custos.Core.Resources.Messages", typeof(Messages).Assembly);

    /// <summary>Language of the texts. Null: the UI language of the current thread.</summary>
    public static CultureInfo? Culture { get; set; }

    /// <summary>The culture texts are looked up in.</summary>
    public static CultureInfo UiCulture => Culture ?? CultureInfo.CurrentUICulture;

    /// <summary>The culture numbers and dates are formatted with.</summary>
    public static CultureInfo FormatCulture => Culture ?? CultureInfo.CurrentCulture;

    public static bool IsRussian => UiCulture.TwoLetterISOLanguageName == "ru";

    public static string Format(string format, params object?[] args) => string.Format(FormatCulture, format, args);

    private static string Get(string name) => Resources.GetString(name, UiCulture) ?? name;
}
